        public Set<String> variables() {
            return constraints.keySet();
        }
    }

    private static class VariableConstraint {
        private BigInteger min;
        private BigInteger max;
        private BigInteger exact; // null if not exact

        private VariableConstraint() {}

        public static VariableConstraint any() {
            VariableConstraint c = new VariableConstraint();
            c.min = BigInteger.valueOf(Long.MIN_VALUE);
            c.max = BigInteger.valueOf(Long.MAX_VALUE);
            c.exact = null;
            return c;
        }

        public static VariableConstraint exact(BigInteger v) {
            VariableConstraint c = new VariableConstraint();
            c.min = v;
            c.max = v;
            c.exact = v;
            return c;
        }

        public static VariableConstraint range(BigInteger min, BigInteger max) {
            VariableConstraint c = new VariableConstraint();
            c.min = min;
            c.max = max;
            c.exact = null;
            return c;
        }

        public VariableConstraint intersect(VariableConstraint other) {
            BigInteger newMin = min.max(other.min);
            BigInteger newMax = max.min(other.max);
            if (newMin.compareTo(newMax) > 0) {
                return null; // empty
            }
            VariableConstraint result = new VariableConstraint();
            result.min = newMin;
            result.max = newMax;
            if (exact != null && other.exact != null && exact.equals(other.exact)) {
                result.exact = exact;
            } else if (exact != null && exact.compareTo(other.min) >= 0 && exact.compareTo(other.max) <= 0) {
                result.exact = exact;
            } else if (other.exact != null && other.exact.compareTo(min) >= 0 && other.exact.compareTo(max) <= 0) {
                result.exact = other.exact;
            }
            return result;
        }

        public VariableConstraint union(VariableConstraint other) {
            BigInteger newMin = min.min(other.min);
            BigInteger newMax = max.max(other.max);
            VariableConstraint result = new VariableConstraint();
            result.min = newMin;
            result.max = newMax;
            result.exact = null;
            return result;
        }
